import React, {useState, useEffect, useMemo, useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowUpRight, ArrowRight, ArrowDownToLine, Plus, Search, ChevronDown, ChevronRight, X, Menu, Bell, LayoutDashboard, Building2, Sparkles, Send, MessagesSquare, Target, Plug, Route, FolderOpen, ClipboardCheck, KeyRound, ListChecks, ShieldCheck, History, FileText, Globe2, CircleHelp, Check, Clock3, CheckCircle2, AlertCircle, LoaderCircle, Eye, Mail, CalendarDays, LockKeyhole, WandSparkles, RefreshCw, MoreHorizontal, Upload, Users, ChevronLeft, Filter, LogOut, ExternalLink, CheckCheck, CircleDollarSign, Layers3, Workflow} from 'lucide-react';
import './styles.css';
import './legibility.css';
import './motion.css';
import {FlowModel} from './flows.jsx';
const PresentationHub=React.lazy(()=>import('./PresentationHub.jsx').then(m=>({default:m.PresentationHub})));
import {ProspectingWorkbench,CompanyIntelligence,CampaignQualification} from './ProspectingWorkbench.jsx';
import {DocumentWorkspace} from './DocumentWorkspace.jsx';
import {AnalyticsDashboard} from './AnalyticsDashboard.jsx';
import {OpportunityBoard,EnrichmentWorkspace,MailWorkspace,CommercialSettings} from './CommercialWorkspace.jsx';
import {ContractSettings} from './ContractSettings.jsx';
import {ThemeToggle} from './Theme.jsx';
import './theme.css';
import './dark-overrides.css';

// Perfil con el que abre cada aplicación (decisión del usuario, 16-10-2026).
const DEFAULT_PROFILE={prospectador:'agustin-silva',contratos:'gonzalo-oviedo'};
const COUNTRY={CL:'Chile',UY:'Uruguay',PE:'Perú',AR:'Argentina',MX:'México'};
const NAV={prospectador:[['resumen','Resumen',LayoutDashboard],['flujo','Flujo y datos',Workflow],['cartera','Mi cartera',Building2],['descubrir','Descubrir prospectos',Sparkles],['enriquecer','Contactos y créditos',Users],['campanas','Campañas',Send],['seguimiento','Seguimiento',MessagesSquare],['resultados','Propuestas y resultados',Target],['integraciones','Integraciones',Plug],['configuracion','Agentes y reglas',WandSparkles],['roadmap','Alcance y roadmap',Route]],contratos:[['resumen','Resumen',LayoutDashboard],['flujo','Flujo y datos',Workflow],['repositorio','Repositorio',FolderOpen],['trabajo','Mi trabajo',ClipboardCheck],['obligaciones','Obligaciones',ListChecks],['antecedentes','Antecedentes',Layers3],['accesos','Accesos regionales',KeyRound],['auditoria','Auditoría',History],['configuracion','Tipos, plantillas y flujos',Workflow],['integraciones','Integraciones',Plug],['roadmap','Alcance y roadmap',Route]]};
const LABELS={en_revision:'En revisión',pendiente_aprobacion:'Por aprobar',pendiente_firma:'Por firmar',en_renovacion:'En renovación',no_contactar:'No contactar',respondió:'Respondió',negociacion:'Negociación',outbound:'Saliente',inbound:'Entrante',aprobado:'Aprobado',rechazado:'Rechazado',activo:'Activo',borrador:'Borrador',firmado:'Firmado',restringido:'Restringido',calificada:'Calificada',propuesta:'Propuesta',ganado:'Ganado',perdido:'Perdido',enviada:'Enviada',aprobada:'Aprobada',pendiente:'Pendiente',completada:'Completada',contactado:'Contactado',nuevo:'Nuevo',reunión:'Reunión',revelado:'Revelado',programada:'Programada',simulado:'Simulado'};
const label=s=>LABELS[s]||String(s||'Sin estado').replaceAll('_',' ');
const num=n=>new Intl.NumberFormat('es-CL').format(Number(n)||0);
const money=(n,c='USD')=>new Intl.NumberFormat('es-CL',{style:'currency',currency:c,maximumFractionDigits:0}).format(Number(n)||0);
const date=d=>d?new Date(d.length===10?`${d}T12:00:00`:d).toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'}):'—';
const nextDate=(days=7)=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);
function Badge({children,status}){return <span className={`badge badge-${status||'neutral'}`}>{children||label(status)}</span>}
function Avatar({name='',small=false}){return <span className={`avatar ${small?'small':''}`}>{name.split(' ').slice(0,2).map(p=>p[0]).join('')}</span>}
function Empty({title='Todavía no hay registros',text='Los registros que cree en esta demostración aparecerán aquí.',action}){return <div className="empty"><FolderOpen size={30}/><h3>{title}</h3><p>{text}</p>{action}</div>}
function Button({children,icon:Icon,onClick,secondary=false,ghost=false,danger=false,small=false,...props}){return <button className={`btn ${secondary?'secondary':''} ${ghost?'ghost':''} ${danger?'danger':''} ${small?'btn-sm':''}`} onClick={onClick} {...props}>{Icon&&<Icon size={16}/>} {children}</button>}
function Field({title,children,hint}){const hintId=React.useId();const control=React.isValidElement(children)&&['input','select','textarea'].includes(children.type);const input=control?React.cloneElement(children,{'aria-label':title,'aria-describedby':hint?hintId:undefined}):children;const Wrapper=control?'label':'div';return <Wrapper className="field"><span>{title}</span>{input}{hint&&<small id={hintId}>{hint}</small>}</Wrapper>}
function App(){
  const app=location.pathname.startsWith('/prospectador')?'prospectador':location.pathname.startsWith('/contratos')?'contratos':null;
  const [profile,setProfile]=useState(()=>{try{const own=localStorage.getItem(`vertia-demo-profile-v3-${app}`);if(own)return own}catch{}return DEFAULT_PROFILE[app]||'regional'});
  const refreshSequence=useRef(0);
  const [state,setState]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const [section,setSection]=useState('resumen'),[country,setCountry]=useState('all'),[query,setQuery]=useState(''),[mobile,setMobile]=useState(false),[toast,setToast]=useState(null),[modal,setModal]=useState(null),[detail,setDetail]=useState(null),[detailTab,setDetailTab]=useState('resumen'),[notifications,setNotifications]=useState(false),[statusFilter,setStatusFilter]=useState('all'),[drill,setDrill]=useState(null);
  async function request(url,options={}){const r=await fetch(url,{...options,headers:{'X-Demo-User':profile,...(options.body&&!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers}});if(!r.ok){let e;try{e=await r.json()}catch{e={detail:`El servidor respondió ${r.status}`}}const failure=new Error(typeof e.detail==='string'?e.detail:e.detail?.message||JSON.stringify(e.detail));failure.detail=e.detail;failure.status=r.status;failure.retryAfter=r.headers.get('Retry-After');throw failure}return r}
  async function refresh(silent=false){if(!app)return;const sequence=++refreshSequence.current; if(!silent)setLoading(true);setError('');try{const data=await(await request(`/api/state?app=${app}`)).json();if(sequence===refreshSequence.current)setState(data)}catch(e){if(sequence===refreshSequence.current)setError(e.message)}finally{if(sequence===refreshSequence.current)setLoading(false)}}
  useEffect(()=>{try{localStorage.setItem(`vertia-demo-profile-v3-${app}`,profile)}catch{}setDrill(null);setDetail(null);setModal(null);setCountry('all');refresh()},[profile,app]);
  useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(null),5500);return()=>clearTimeout(t)}},[toast]);
  useEffect(()=>{function esc(e){if(e.key==='Escape'){setModal(null);setDetail(null);setMobile(false);setNotifications(false)}}window.addEventListener('keydown',esc);return()=>window.removeEventListener('keydown',esc)},[]);
  async function action(name,id,payload={},close=false){setBusy(true);try{const data=await(await request('/api/actions',{method:'POST',body:JSON.stringify({app,action:name,entity_id:id||null,payload})})).json();await refresh(true);const e=data.entity||{};const moment=name==='send_campaign'?{title:e.status==='enviada'?'Campaña enviada':'Campaña en cola',message:`${e.sent_count??0} envíos simulados registrados y ${e.queued_count??0} pendientes del horario y ritmo permitido. Ningún correo salió de la aplicación.`}:name==='sign_contract'?{title:'Contrato firmado',message:'Firma simulada registrada, sin efecto legal. Siguiente paso: activar el contrato.'}:null;setToast(moment?{...moment,type:'success',moment:true}:{message:data.message||'Cambios guardados',type:'success'});if(close)setModal(null);return data}catch(e){window.dispatchEvent(new CustomEvent('vertia-api-error',{detail:{status:e.status,detail:e.detail,retryAfter:e.retryAfter}}));setToast({message:e.message,type:'error'});return null}finally{setBusy(false)}}
  async function download(url,filename,open=false){try{const r=await request(url),blob=await r.blob(),u=URL.createObjectURL(blob);if(open){const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener';a.click()}else{const a=document.createElement('a');a.href=u;a.download=filename;a.click()}setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(e){setToast({message:e.message,type:'error'})}}
  const visible=(rows=[],kind)=>rows.filter(r=>(country==='all'||r.country===country)&&(!query||JSON.stringify(r).toLocaleLowerCase().includes(query.toLocaleLowerCase()))&&(!drill||drill.kind!==kind||drill.ids.includes(r.id)));
  const S=state||{},companies=visible(S.companies,'companies'),contacts=visible(S.contacts,'contacts'),contracts=visible(S.contracts,'contracts'),campaigns=visible(S.campaigns,'campaigns'),prospects=visible(S.prospects,'prospects'),activities=visible(S.activities,'activities'),opportunities=visible(S.opportunities,'opportunities'),obligations=visible(S.obligations,'obligations'),access=visible(S.access_requests,'access_requests'),audits=visible(S.audit,'audit'),m=S.metrics||{};
  const current=detail?([...(S.contracts||[]),...(S.contacts||[]),...(S.campaigns||[]),...(S.companies||[])].find(r=>r.id===detail.id)||detail):null;
  const crm=app==='prospectador',isLeader=['regional','manager','legal','superadmin'].includes(S.viewer?.role),readOnly=['viewer','innovation_admin'].includes(S.viewer?.role),noCommercial=readOnly||['legal','ia_lead'].includes(S.viewer?.role);
  const openDetail=(r,tab='resumen')=>{setDetail(r);setDetailTab(r.sanitized_only?'documentos':tab)};
  const openForm=(type,entity)=>setModal({type,entity});
  const clmConfig=(S.clm_settings||[]).reduce((best,r)=>(r.version||0)>(best?.version||0)?r:best,null)?.settings;
  const go=s=>{setSection(s);setDrill(null);setStatusFilter('all');setMobile(false);setQuery('');setDetail(null)};

  function renderForm(){
    const type=modal.type,e=modal.entity||{};
    const config={company:['Nueva empresa','create_company'],contact:['Nuevo contacto','create_contact'],editcontact:['Editar contacto','update_contact'],editcompany:['Editar empresa','update_company'],campaign:['Nueva campaña','create_campaign'],opportunity:['Registrar oportunidad','set_opportunity'],contract:['Nuevo contrato','create_contract'],upload:['Adjuntar documento sintético','upload_document'],obligation:['Nueva obligación','add_obligation'],amendment:['Registrar enmienda','add_amendment'],renew:['Proponer renovación','renew_contract'],access:['Solicitar acceso temporal','request_access'],meeting:['Agendar reunión','log_meeting'],reply:['Simular respuesta recibida','receive_reply'],exclude:['Excluir contacto','exclude_contact'],reject:['Rechazar contrato','reject_contract'],complete:['Registrar cumplimiento','complete_obligation'],import:['Importar contactos','import_contacts']}[type];
    if(!config)return null;
    const [title,act]=config;
    async function submit(ev){ev.preventDefault();let p=Object.fromEntries(new FormData(ev.currentTarget));if(['campaign'].includes(type))p.contact_ids=new FormData(ev.currentTarget).getAll('contact_ids');if(p.amount)p.amount=Number(p.amount);if(type==='contact')p.country=(S.companies||[]).find(c=>c.id===p.company_id)?.country||S.viewer.country;if(type==='contract')p.confidential=p.confidential==='on';if(type==='import'){try{const lines=p.csv.trim().split(/\r?\n/).filter(Boolean);p={rows:lines.map(line=>{const [name,email,title]=line.split(';').map(t=>t.trim());return{name,email,title,company_id:p.company_id,country:(S.companies||[]).find(c=>c.id===p.company_id)?.country}})}}catch{setToast({type:'error',message:'Revise el formato de las filas'});return}}await action(act,e.id,p,true)}
    return <div className="overlay modal-overlay" onClick={()=>!busy&&setModal(null)}><div className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><div className="modal-heading"><div><span className="eyebrow">{crm?'GLOBAL VÍA PÚBLICA':'VERTIA'} · DEMOSTRACIÓN</span><h2>{title}</h2></div><button className="icon-btn" onClick={()=>setModal(null)} aria-label="Cerrar"><X size={21}/></button></div><form onSubmit={submit}>
    {['company','editcompany'].includes(type)&&<><Field title="Nombre de empresa"><input name="name" required defaultValue={e.name} placeholder="Ej. Horizonte Retail" autoFocus/></Field>{type==='company'&&<Field title="Dominio sintético" hint="Solo se admiten dominios de demostración .example"><input name="domain" required defaultValue="horizonte.example"/></Field>}<Field title="Sector"><select name="sector" defaultValue={e.sector||'Retail'}>{['Retail','Tecnología','Consumo masivo','Servicios financieros','Telecomunicaciones','Otros'].map(x=><option key={x}>{x}</option>)}</select></Field>{type==='company'&&CountryField()}</>}
    {['contact','editcontact'].includes(type)&&<><Field title="Nombre completo"><input required name="name" defaultValue={e.name} autoFocus placeholder="Ej. Alex González"/></Field><Field title="Cargo"><input name="title" defaultValue={e.title||'Responsable de Marketing'}/></Field>{type==='contact'&&<><Field title="Empresa"><select name="company_id" required defaultValue={e.company_id||''}><option value="" disabled>Seleccione una empresa</option>{(S.companies||[]).map(c=><option value={c.id} key={c.id}>{c.name} · {c.country}</option>)}</select></Field><Field title="Correo sintético" hint="No se envían correos. Utilice .example"><input required name="email" type="email" placeholder="alex@horizonte.example"/></Field></>}<Field title="Teléfono"><input name="phone" defaultValue={e.phone||''} placeholder="Teléfono de demostración"/></Field></>}
    {type==='import'&&<><div className="callout">Cada fila usa el formato nombre;correo;cargo, sin encabezado. Se omiten correos ya registrados.</div><Field title="Empresa de destino"><select required name="company_id"><option value="">Seleccione empresa</option>{(S.companies||[]).map(c=><option value={c.id} key={c.id}>{c.name} · {c.country}</option>)}</select></Field><Field title="Contactos (hasta 100)" hint="Use exclusivamente direcciones .example"><textarea name="csv" rows={7} required placeholder={'Alex Silva;alex@empresa.example;Gerente\nMaría Vega;maria@empresa.example;Marketing'}/></Field></>}
    {type==='campaign'&&<><Field title="Nombre de campaña"><input required name="name" placeholder="Ej. Cobertura regional · Retail" autoFocus/></Field><CountryNotice/><Field title="Asunto"><input name="subject" defaultValue="Una nueva oportunidad de visibilidad" required/></Field><Field title="Mensaje inicial"><textarea name="body" rows={3} required defaultValue="Estimado equipo, nos gustaría conversar sobre sus objetivos de comunicación y cobertura."/></Field><Field title="Destinatarios" hint="Seleccione contactos de un mismo país. Los excluidos no están disponibles."><div className="check-list">{(S.contacts||[]).filter(c=>!c.excluded).map(c=><label key={c.id}><input name="contact_ids" type="checkbox" value={c.id}/><span><b>{c.name}</b><small>{c.company_name} · {c.country}</small></span></label>)}</div></Field></>}
    {type==='opportunity'&&<><Field title="Nombre de oportunidad"><input required name="name" autoFocus defaultValue={e.name} placeholder="Ej. Campaña primavera 2027"/></Field><Field title="Empresa"><select required name="company_id" defaultValue={e.company_id||''}><option value="">Seleccione empresa</option>{(S.companies||[]).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><div className="form-grid"><Field title="Monto"><input required name="amount" type="number" min="0" step="0.01" defaultValue={e.amount||10000}/></Field><Field title="Moneda"><select name="currency" defaultValue={e.currency||'USD'}>{['USD','CLP','PEN','ARS','MXN','UYU'].map(c=><option key={c}>{c}</option>)}</select></Field></div><Field title="Etapa"><select name="status" defaultValue={e.status||'propuesta'}>{['nuevo','calificada','propuesta','negociacion','ganado','perdido'].map(s=><option key={s} value={s}>{label(s)}</option>)}</select></Field></>}
    {type==='contract'&&<><Field title="Nombre del contrato"><input required name="title" autoFocus placeholder="Ej. Acuerdo de servicios regionales"/></Field><div className="form-grid"><Field title="Sociedad Vertia"><input required name="company" defaultValue={`Vertia ${COUNTRY[S.viewer?.country]||'Chile'}`}/></Field><Field title="Contraparte"><input name="counterparty" required placeholder="Ej. Horizonte Servicios"/></Field></div>{CountryField()}<div className="form-grid"><Field title="Tipo"><select name="type">{(clmConfig?.types||['Comercial','Servicios','Arrendamiento','Confidencialidad','Alianza','Laboral']).map(t=><option key={t}>{t}</option>)}</select></Field><Field title="Vencimiento"><input required type="date" name="end_date" defaultValue={nextDate(365)}/></Field></div><div className="form-grid"><Field title="Monto referencial"><input name="amount" required type="number" min="0" step="0.01" defaultValue="25000"/></Field><Field title="Moneda"><select name="currency">{['USD','CLP','PEN','ARS','MXN','UYU'].map(c=><option key={c}>{c}</option>)}</select></Field></div><label className="checkbox-line"><input type="checkbox" name="confidential" defaultChecked/> Contiene información confidencial</label></>}
    {type==='upload'&&<><div className="callout"><ShieldCheck size={18}/> Se crea un documento sintético en el servidor. Esta demostración no carga ni almacena archivos reales.</div><Field title="Nombre del documento"><input required name="filename" defaultValue="contrato-demostracion.pdf" autoFocus/></Field><Field title="Tipo documental"><select name="kind"><option value="contrato">Contrato</option><option value="anexo">Anexo</option><option value="carta">Carta de experiencia</option><option value="antecedente">Antecedente</option></select></Field></>}
    {type==='obligation'&&<><Field title="Obligación"><input required name="title" placeholder="Ej. Enviar informe trimestral" autoFocus/></Field><Field title="Responsable"><input name="owner" defaultValue={S.viewer.name}/></Field><Field title="Fecha de cumplimiento"><input required type="date" name="due_date" defaultValue={nextDate(30)}/></Field></>}
    {type==='amendment'&&<><Field title="Título de enmienda"><input required name="title" placeholder="Ej. Ampliación de cobertura" autoFocus/></Field><Field title="Descripción"><textarea name="description" rows={4}/></Field><Field title="Nuevo vencimiento (opcional)"><input type="date" name="new_end_date"/></Field></>}
    {type==='renew'&&<><div className="callout">La renovación vuelve a abrir el ciclo de revisión. Fecha actual: {date(e.end_date)}.</div><Field title="Nuevo vencimiento"><input required name="end_date" type="date" defaultValue={new Date(new Date(e.end_date).getTime()+365*86400000).toISOString().slice(0,10)} min={e.end_date}/></Field></>}
    {type==='meeting'&&<><Field title="Título de la reunión"><input name="title" required defaultValue={`Reunión comercial · ${e.company_name}`}/></Field><Field title="Fecha y hora"><input type="datetime-local" required name="date" defaultValue={`${nextDate(2)}T10:00`}/></Field><div className="callout">Calendario simulado. No se envían invitaciones externas.</div></>}
    {['access','exclude','reject'].includes(type)&&<Field title={type==='access'?'Motivo de la solicitud':'Motivo'}><textarea name="reason" required rows={4} autoFocus defaultValue={type==='access'?'Consulta de antecedente para propuesta regional.':type==='exclude'?'Solicitud de no contacto.':''}/></Field>}
    {type==='reply'&&<><Field title="Respuesta sintética"><textarea name="body" rows={4} required autoFocus defaultValue="Nos interesa conocer la propuesta. ¿Podemos coordinar una reunión?"/></Field><div className="callout">La respuesta detiene automáticamente los seguimientos de este contacto.</div></>}
    {type==='complete'&&<Field title="Evidencia de cumplimiento"><textarea name="evidence" rows={4} required autoFocus placeholder="Describa el cumplimiento registrado en esta demostración"/></Field>}
    <div className="modal-footer"><Button secondary onClick={()=>setModal(null)} type="button">Cancelar</Button><Button disabled={busy} icon={busy?null:Check} type="submit">{busy?'Guardando…':'Guardar y continuar'}</Button></div></form></div></div>
  }
  function CountryField(){return <Field title="País"><select name="country" defaultValue={country==='all'?S.viewer?.country:country}>{(S.countries||[]).filter(c=>['regional','superadmin'].includes(S.viewer?.role)||c.code===S.viewer?.country).map(c=><option key={c.code} value={c.code}>{c.name}</option>)}</select></Field>}
  function CountryNotice(){return <div className="callout">Cada campaña corresponde a un país y requiere aprobación de jefatura antes del envío simulado.</div>}
  function SectionHead({eyebrow,title,description,children}){return <div className="section-heading"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{description&&<p>{description}</p>}</div><div className="heading-actions">{children}</div></div>}
  function Panel({title,subtitle,children,action:act,className=''}){return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{act}</div>{children}</section>}
  function CountryPill({code}){return <span className="country-pill"><span className="country-code">{code}</span>{COUNTRY[code]||code}</span>}
  function ContractTable({rows=contracts,compact=false}){return rows.length?<div className="table-scroll"><table><thead><tr><th>Contrato / referencia</th><th>País</th><th>Estado</th>{!compact&&<><th>Vencimiento</th><th>Valor</th></>}<th aria-label="Acciones"/></tr></thead><tbody>{rows.map(c=><tr key={c.id} onClick={()=>openDetail(c)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&openDetail(c)}><td><div className="cell-with-icon"><span className={`file-icon ${c.restricted?'locked':''}`}>{c.restricted?<LockKeyhole size={17}/>:<FileText size={18}/>}</span><div><b>{c.title}</b><small>{c.reference}{!c.restricted&&` · ${c.type}`}</small></div></div></td><td><CountryPill code={c.country}/></td><td><Badge status={c.status}/></td>{!compact&&<><td>{date(c.end_date)}</td><td className="money-cell">{c.restricted?'Información reservada':`${money(c.amount,c.currency)} ${c.currency}`}</td></>}<td><ChevronRight size={16}/></td></tr>)}</tbody></table></div>:<Empty title="No hay contratos para esta vista" text="Ajuste sus filtros o cree un nuevo contrato sintético."/>}
  function ContactTable({rows=contacts}){return rows.length?<div className="table-scroll"><table><thead><tr><th>Contacto</th><th>Empresa</th><th>País</th><th>Estado</th><th>Afinidad</th><th/></tr></thead><tbody>{rows.map(c=><tr key={c.id} onClick={()=>openDetail(c)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&openDetail(c)}><td><div className="cell-with-icon"><Avatar name={c.name}/><div><b>{c.name}</b><small>{c.title}</small></div></div></td><td><b className="normal-weight">{c.company_name}</b><small>{c.email}</small></td><td><CountryPill code={c.country}/></td><td><Badge status={c.excluded?'no_contactar':c.status}/></td><td><span className="score"><i style={{width:`${Math.min(c.score||0,100)}%`}}/>{c.score||'—'}</span></td><td><ChevronRight size={16}/></td></tr>)}</tbody></table></div>:<Empty title="Su cartera está lista para crecer" text="Cree una empresa y agregue su primer contacto sintético."/>}
  function Overview(){return <AnalyticsDashboard S={S} app={app} country={country} readOnly={crm?noCommercial:readOnly} onOpen={openDetail} onCreate={()=>openForm(crm?'company':'contract')} onExport={()=>download(`/api/export?app=${app}`,`${app}.csv`)} onDrill={d=>{go(d.section);setDrill(d)}}/>}
  function Portfolio(){return <><SectionHead eyebrow="GESTIÓN COMERCIAL" title="Mi cartera" description="Empresas y contactos organizados por responsable, país y etapa."><Button secondary icon={Upload} disabled={noCommercial} onClick={()=>openForm('import')}>Importar</Button><Button secondary icon={Plus} disabled={noCommercial} onClick={()=>openForm('company')}>Empresa</Button><Button icon={Plus} disabled={noCommercial||!(S.companies||[]).length} onClick={()=>openForm('contact')}>Nuevo contacto</Button></SectionHead><div className="company-strip">{companies.slice(0,6).map(c=><button key={c.id} className="company-mini" onClick={()=>openDetail(c,'empresa')}><span className="company-mark">{c.name.slice(0,1)}</span><span><b>{c.name}</b><small>{c.sector} · {c.country}</small></span><ChevronRight size={15}/></button>)}</div><Panel title="Contactos de su cartera" subtitle={`${contacts.length} contactos visibles · los excluidos conservan su historial`} action={<select className="compact-select" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">Todos los estados</option>{['nuevo','contactado','respondió','reunión','no_contactar'].map(s=><option value={s} key={s}>{label(s)}</option>)}</select>}><ContactTable rows={contacts.filter(c=>statusFilter==='all'||c.status===statusFilter)}/></Panel></>}
  function Campaigns(){return <><SectionHead eyebrow="ACTIVACIÓN COMERCIAL" title="Campañas con criterio humano." description="Prepare mensajes, revise destinatarios y apruebe cada envío."><Button icon={Plus} disabled={noCommercial} onClick={()=>openForm('campaign')}>Nueva campaña</Button></SectionHead><div className="process-strip">{['Seleccionar contactos','Preparar mensaje','Aprobar','Enviar y medir'].map((t,i)=><React.Fragment key={t}><span><i>{i+1}</i>{t}</span>{i<3&&<ChevronRight size={16}/>}</React.Fragment>)}</div><Panel title="Campañas" subtitle="El envío y la generación con Claude son simulados; la aprobación y los estados persisten en PostgreSQL.">{campaigns.length?<div className="table-scroll"><table><thead><tr><th>Campaña</th><th>Mercado</th><th>Estado</th><th>Destinatarios</th><th>Enviados</th><th>Acción</th></tr></thead><tbody>{campaigns.map(c=><tr key={c.id}><td><div className="cell-with-icon"><span className="file-icon"><Send size={17}/></span><div><button className="cell-link" onClick={()=>openDetail(c,'campana')}>{c.name}</button><small>{c.subject}</small></div></div></td><td><CountryPill code={c.country}/></td><td><Badge status={c.status}/></td><td>{c.contact_ids?.length||0}</td><td>{c.sent_count||0}</td><td><Button small secondary icon={ArrowUpRight} onClick={()=>openDetail(c,'campana')}>Abrir</Button></td></tr>)}</tbody></table></div>:<Empty title="Su primera campaña comienza aquí" action={<Button icon={Plus} disabled={noCommercial} onClick={()=>openForm('campaign')}>Crear campaña</Button>}/>}</Panel></>}
  function Repository({work=false,antecedent=false}){const rows=contracts.filter(c=>statusFilter==='all'||c.status===statusFilter).filter(c=>!work||['en_revision','pendiente_aprobacion','pendiente_firma','borrador'].includes(c.status)).filter(c=>!antecedent||!c.restricted);return <><SectionHead eyebrow={antecedent?'MEMORIA CONTRACTUAL':'GESTIÓN CONTRACTUAL'} title={work?'Mi trabajo':antecedent?'Antecedentes reutilizables':'Repositorio de contratos'} description={work?'Las decisiones pendientes, ordenadas en una sola vista.':antecedent?'Consulte experiencias y genere copias saneadas antes de compartir información.':'Un expediente por contrato: documentos, decisiones, obligaciones y trazabilidad.'}><Button secondary icon={ArrowDownToLine} onClick={()=>download('/api/export?app=contratos','contratos.csv')}>Exportar</Button>{!antecedent&&<Button icon={Plus} disabled={readOnly} onClick={()=>openForm('contract')}>Nuevo contrato</Button>}</SectionHead>{antecedent&&<div className="info-banner"><ShieldCheck size={24}/><div><b>La información sensible permanece bajo control.</b><p>La copia saneada se construye a partir de campos permitidos, requiere revisión humana y mantiene trazabilidad de la versión de origen.</p></div></div>}<Panel title={work?'Pendientes visibles':antecedent?'Contratos disponibles para consulta':'Todos los expedientes'} subtitle={`${rows.length} registros en esta vista`} action={<select className="compact-select" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">Todos los estados</option>{['borrador','en_revision','aprobado','pendiente_firma','firmado','activo','rechazado','en_renovacion','restringido'].map(s=><option key={s} value={s}>{label(s)}</option>)}</select>}><ContractTable rows={rows}/></Panel></>}
  function Obligations(){return <><SectionHead eyebrow="CONTROL DE COMPROMISOS" title="Nada importante queda pendiente." description="Responsables, vencimientos y evidencias vinculados al expediente contractual."/><Panel title="Obligaciones contractuales" subtitle="Para crear una obligación, abra la ficha de un contrato autorizado.">{obligations.length?<div className="table-scroll"><table><thead><tr><th>Compromiso</th><th>Contrato</th><th>Responsable</th><th>Vencimiento</th><th>Estado</th><th/></tr></thead><tbody>{obligations.map(o=><tr key={o.id}><td><b>{o.title}</b>{o.evidence&&<small>{o.evidence}</small>}</td><td><button className="cell-link" onClick={()=>{const c=(S.contracts||[]).find(c=>c.id===o.contract_id);if(c)openDetail(c,'obligaciones')}}>{(S.contracts||[]).find(c=>c.id===o.contract_id)?.reference||o.contract_id}</button></td><td>{o.owner||'Responsable local'}</td><td><span className={o.status!=='completada'&&o.due_date<nextDate(0)?'overdue':''}>{date(o.due_date)}</span></td><td><Badge status={o.status}/></td><td>{o.status!=='completada'&&<Button small secondary icon={Check} disabled={readOnly||busy} onClick={()=>openForm('complete',o)}>Completar</Button>}</td></tr>)}</tbody></table></div>:<Empty title="Compromisos bajo control" text="Abra un contrato y agregue su primera obligación."/>}</Panel></>}
  function Access(){return <><SectionHead eyebrow="COLABORACIÓN REGIONAL" title="Compartir con autorización." description="El país de origen conserva el control. El acceso entre países es temporal y de consulta."/><div className="info-banner"><KeyRound size={24}/><div><b>Pruebe el recorrido completo con los perfiles de demostración.</b><p>Seleccione el perfil de consulta de Argentina, solicite un contrato de otro país y cambie al perfil regional para autorizar. Al volver al perfil solicitante podrá consultar el expediente.</p></div></div><Panel title="Solicitudes de acceso" subtitle="Las aprobaciones pueden durar entre 1 y 30 días.">{access.length?<div className="table-scroll"><table><thead><tr><th>Solicitud</th><th>Solicitante</th><th>País origen</th><th>Estado</th><th>Vigencia</th><th/></tr></thead><tbody>{access.map(a=><tr key={a.id}><td><b>{(S.contracts||[]).find(c=>c.id===a.contract_id)?.reference||'Contrato regional'}</b><small>{a.reason}</small></td><td>{a.requester_name||a.requested_by}</td><td><CountryPill code={a.country}/></td><td><Badge status={a.status}/></td><td>{a.expires_at?date(a.expires_at):'Pendiente'}</td><td>{a.status==='pendiente'&&isLeader&&<Button small secondary disabled={busy} icon={Check} onClick={()=>action('grant_access',a.id,{days:7})}>Autorizar 7 días</Button>}</td></tr>)}</tbody></table></div>:<Empty title="Sin solicitudes en este perfil" text="Solicite acceso desde un contrato restringido en el repositorio."/>}</Panel><Panel title="Catálogo regional restringido" subtitle="Solo se muestra una referencia sintética; los contenidos requieren autorización."><ContractTable rows={contracts.filter(c=>c.restricted)} compact/></Panel></>}
  function Audit(){return <><SectionHead eyebrow="TRAZABILIDAD OPERACIONAL" title="Cada decisión deja registro." description="Historial de acciones persistido para los registros visibles de su perfil."/><Panel title="Registro de actividad" subtitle="Bitácora de demostración; no constituye almacenamiento inmutable WORM.">{audits.length?<div className="table-scroll"><table><thead><tr><th>Evento</th><th>Responsable</th><th>País</th><th>Fecha</th><th>Detalle</th></tr></thead><tbody>{audits.map(a=><tr key={a.id}><td><b>{a.title||label(a.action)}</b><small>{a.entity_id}</small></td><td>{a.actor_name||a.actor}</td><td><CountryPill code={a.country}/></td><td>{date(a.created_at)}</td><td>{a.detail}</td></tr>)}</tbody></table></div>:<Empty title="La actividad aparecerá aquí" text="Cree un registro o ejecute una transición para ver su trazabilidad."/>}</Panel></>}
  function Integrations(){return <><SectionHead eyebrow="ECOSISTEMA TECNOLÓGICO" title="Cada servicio, con un propósito." description="Persistencia real en PostgreSQL y adaptadores externos simulados para esta demostración."/><div className="integration-grid">{(S.integrations||[]).map((i,n)=><article className="integration-card" key={i.id}><div className="integration-symbol">{[<Building2/>,<Sparkles/>,<Mail/>,<WandSparkles/>,<Plug/>][n%5]}</div><div><h2>{i.name}</h2><Badge status={i.status==='conectado'?'activo':'simulado'}>{i.status==='conectado'?'Conectado':'Simulado'}</Badge></div><p>{i.description}</p>{i.name==='POST'&&<Button secondary small icon={RefreshCw} disabled={busy||!isLeader} onClick={()=>action('sync_post')}>Ejecutar conciliación demo</Button>}<footer>{i.status==='conectado'?<><CheckCircle2 size={14}/> Datos persistentes</>:<><ShieldCheck size={14}/> Sin consumos ni envíos reales</>}</footer></article>)}</div><Panel title="Requisitos para producción" subtitle="Servicios provistos y pagados directamente por Vertia"><div className="requirements-list">{[['Infraestructura AWS y PostgreSQL','Ambientes separados de desarrollo, pruebas y producción; acceso seguro, copias de respaldo, monitoreo y recuperación.'],['API Claude','Cuenta, claves y presupuesto de consumo a cargo de Vertia; validación del modelo disponible antes de contratar. Se contemplan agentes, pruebas y producción.'],[crm?'Datos comerciales y Microsoft 365':'OCR y firma electrónica',crm?'Licencias de Lusha u otro proveedor autorizado, permisos de Graph, dominios y reglas de contacto definidas por Vertia.':'Consumos OCR por página, licencias de firma y condiciones por país contratados por Vertia.'],['Soporte y mantenimiento','Monitoreo, atención de incidentes, actualizaciones y control de cambios según protocolo y bolsa de horas de la propuesta.']].map(([t,d])=><div key={t}><CheckCircle2 size={18}/><div><h3>{t}</h3><p>{d}</p></div></div>)}</div></Panel></>}
  function Roadmap(){return <><SectionHead eyebrow="ALCANCE Y EVOLUCIÓN" title="Una base sólida. Un camino regional." description="MVP primero, consolidación después y ampliaciones sujetas a evaluación de alcance."><a className="btn secondary" href={`/propuestas/${app}.html`} target="_blank" rel="noreferrer"><FileText size={16}/> Ver propuesta comercial <ArrowUpRight size={15}/></a></SectionHead><div className="roadmap-hero"><div><span className="eyebrow">INVERSIÓN DE DESARROLLO</span><h2>{crm?'USD 13.000':'USD 30.000'} <span>netos</span></h2><p>Referencia en dólares · contratación y cobro en UF · IVA 19% adicional.</p></div><div className="payment-pill"><CircleDollarSign size={25}/><div><b>40% de inicio + 6 cuotas</b><span>{crm?'USD 5.200 + 6 × USD 1.300':'USD 12.000 + 6 × USD 3.000'} netos de referencia</span></div></div></div><div className="roadmap-list">{(crm?[["01","MVP comercial operativo","Incluido","Carteras, descubrimiento y revelación de prospectos, campañas revisadas y aprobadas, respuesta, exclusiones, reuniones y oportunidades."],["02","Validación y puesta en producción","Incluido","Pruebas funcionales, permisos, integraciones contratadas, capacitación, documentación, piloto y estabilización."],["03","Consolidación regional","Incluido","Configuración base de Chile, Perú, Argentina, Uruguay y México. Validación de procesos y datos por responsables locales."],["04","Evolución especializada","Ampliación","WhatsApp, LinkedIn, conectores adicionales y automatizaciones fuera del alcance aprobado se evalúan y cotizan por separado."]]:[["01","MVP contractual controlado","Incluido","Repositorio, versiones, perfiles, revisión, aprobación, firma mediante adaptador, obligaciones y trazabilidad."],["02","Inteligencia documental y operación","Incluido","OCR y análisis asistido con evidencia, revisión humana, copias saneadas, antecedentes, pruebas y salida a producción."],["03","Consolidación regional","Incluido","Configuración de cinco países, acceso temporal de consulta, permisos locales, validación jurídica y capacitación."],["04","Evolución especializada","Ampliación","ERP avanzado, portal externo, add-in Word y analítica predictiva se evalúan y cotizan fuera del alcance inicial."]]).map(([n,t,s,d])=><article key={n}><span className="roadmap-number">{n}</span><div><Badge status={s==='Incluido'?'activo':'neutral'}>{s}</Badge><h2>{t}</h2><p>{d}</p></div><CheckCircle2 size={24}/></article>)}</div><div className="info-banner"><Route size={24}/><div><b>Los ajustes se gestionan con alcance, impacto y aprobación.</b><p>Los refinamientos dentro de los criterios de aceptación se priorizan en el backlog. Nuevos módulos, integraciones o cambios de proceso requieren evaluación y acuerdo comercial. La logística pertenece a una etapa posterior.</p></div></div><Panel title="Lo que demuestra esta maqueta" subtitle="Los precios y el alcance contractual se formalizan en la propuesta independiente."><p className="panel-prose">Los registros, aprobaciones, permisos y transiciones se guardan en PostgreSQL. Los servicios de IA, OCR, firma, datos comerciales, correo y calendario están simulados. La selección de perfil permite revisar escenarios; la autenticación corporativa y los controles de producción corresponden a la implementación. El cronograma definitivo se acuerda al inicio, según entrega de accesos, fuentes y validaciones de Vertia.</p></Panel></>}
  function Detail(){
    const c=current;if(!c)return null;
    const contract=!crm,company=detailTab==='empresa',campaign=detailTab==='campana';
    const editable=contract?c.can_edit:!noCommercial;
    const ownObligations=(S.obligations||[]).filter(o=>o.contract_id===c.id);
    const steps=['borrador','en_revision','aprobado','pendiente_firma','firmado','activo'];
    const transition={borrador:['submit_review','Enviar a revisión',Send],rechazado:['submit_review','Reenviar a revisión',Send],en_revision:['approve_contract','Aprobar contrato',Check],pendiente_aprobacion:['approve_contract','Aprobar contrato',Check],aprobado:['send_signature','Enviar a firma simulada',Send],pendiente_firma:['sign_contract','Registrar firma simulada',CheckCheck],firmado:['activate_contract','Activar contrato',ShieldCheck]}[c.status];
    return <div className="overlay drawer-overlay" onClick={()=>setDetail(null)}><aside className={`drawer ${contract&&detailTab==='documentos'?'drawer-document':company?'drawer-company':''}`} role="dialog" aria-modal="true" aria-label={c.title||c.name} onClick={e=>e.stopPropagation()}><div className="drawer-top"><span className="eyebrow">{contract?'EXPEDIENTE CONTRACTUAL':campaign?'GESTIÓN DE CAMPAÑA':company?'FICHA DE EMPRESA':'FICHA DE CONTACTO'}</span><button className="icon-btn" aria-label="Cerrar ficha" onClick={()=>setDetail(null)}><X size={22}/></button></div><div className="drawer-title"><span className="detail-symbol">{c.restricted?<LockKeyhole size={28}/>:contract?<FileText size={29}/>:campaign?<Send size={28}/>:company?<Building2 size={28}/>:<Users size={28}/>}</span><h2>{contract?c.title:c.name}</h2><p>{c.reference||c.company_name||c.domain||c.subject}</p><div className="detail-badges"><Badge status={c.status}/><CountryPill code={c.country}/>{c.confidential&&<span className="confidential"><LockKeyhole size={12}/> Confidencial</span>}</div></div>
    {c.restricted?<div className="drawer-body"><div className="restricted-box"><LockKeyhole size={32}/><h3>Este expediente requiere autorización.</h3><p>Su perfil puede consultar la referencia del catálogo. Solicite permiso al responsable del país para acceder temporalmente a los documentos y antecedentes.</p><Button icon={KeyRound} disabled={busy} onClick={()=>openForm('access',c)}>Solicitar acceso</Button></div></div>:contract?<><nav className="detail-tabs">{(c.sanitized_only?[['documentos','Extracto autorizado']]:[['resumen','Resumen'],['documentos','Documentos'],['proceso','Proceso'],['obligaciones','Obligaciones'],['historial','Historial']]).map(([k,t])=><button className={detailTab===k?'active':''} key={k} onClick={()=>setDetailTab(k)}>{t}</button>)}</nav><div className="drawer-body">
    {detailTab==='resumen'&&<><div className="detail-facts"><div><small>Sociedad</small><b>{c.company}</b></div><div><small>Contraparte</small><b>{c.counterparty}</b></div><div><small>Monto</small><b>{money(c.amount,c.currency)} {c.currency}</b></div><div><small>Vencimiento</small><b>{date(c.end_date)}</b></div><div><small>Tipo de contrato</small><b>{c.type}</b></div><div><small>Versión vigente</small><b>v{c.version}</b></div></div><div className="detail-section-heading"><h3>Análisis documental</h3><Badge status={c.analysis?.mode==='local_extraction'?'activo':'simulado'}>{c.analysis?.mode==='local_extraction'?'Lectura del archivo · Sin IA externa':'Claude + OCR · Simulado'}</Badge></div>{c.analysis?<><div className="analysis-summary"><span className="analysis-icon"><Sparkles size={22}/></span><div><h3>Revisión humana requerida</h3><p>{c.analysis.summary}</p><small>Fuente: versión {c.analysis.source_version||c.version} · {date(c.analysis.analyzed_at)}</small></div></div><div className="findings">{c.analysis.findings.map((f,i)=><article key={i}><header><h4>{f.title}</h4><Badge status={f.severity==='alta'?'no_contactar':'pendiente'}>Riesgo {f.severity}</Badge></header><blockquote>“{f.evidence}” <span>p. {f.page}</span></blockquote><p>{f.recommendation}</p></article>)}</div></>:<div className="callout">Analice un documento para identificar campos y hallazgos con referencia a la fuente. El análisis de esta maqueta es sintético.</div>}{c.analysis?.mode==='local_extraction'?<Button secondary icon={FileText} onClick={()=>setDetailTab('documentos')}>Revisar extracción y original</Button>:<Button secondary icon={WandSparkles} disabled={!editable||busy||!c.documents?.length} onClick={()=>action('analyze_contract',c.id)}>{c.analysis?'Actualizar análisis simulado':'Analizar documento'}</Button>}<div className="detail-section-heading"><h3>Enmiendas y renovación</h3><Badge status="neutral">Vista evolutiva</Badge></div>{(c.amendments||[]).map(a=><div className="amendment" key={a.id}><b>{a.title}</b><p>{a.description}</p><small>{date(a.at)}</small></div>)}<div className="button-row"><Button secondary small icon={Plus} disabled={!editable||!['activo','firmado','en_renovacion'].includes(c.status)} onClick={()=>openForm('amendment',c)}>Registrar enmienda</Button><Button secondary small icon={RefreshCw} disabled={!editable||!['activo','vencido','en_renovacion'].includes(c.status)} onClick={()=>openForm('renew',c)}>Proponer renovación</Button></div></>}
    {detailTab==='documentos'&&<DocumentWorkspace contract={c} profile={profile} request={request} refresh={refresh} action={action} editable={editable} isLeader={isLeader} download={download} busy={busy}/>}
    {detailTab==='proceso'&&<><h3>Ciclo contractual</h3><div className="vertical-process">{steps.map((s,i)=><div className={steps.indexOf(c.status)>=i?'done':''} key={s}><span>{steps.indexOf(c.status)>i?<Check size={15}/>:i+1}</span><div><b>{label(s)}</b><small>{['Preparación y documentos','Validación de antecedentes y hallazgos','Decisión de jefatura o Legal','Adaptador de firma simulado','Firma registrada en la demostración','Seguimiento de compromisos'][i]}</small></div>{c.status===s&&<Badge status="activo">Actual</Badge>}</div>)}</div><div className="callout">La aprobación exige un perfil de jefatura, Legal o regional. La firma es simulada y no produce efectos legales.</div>{transition&&<Button icon={transition[2]} disabled={!editable||busy||(transition[0]!=='submit_review'&&!isLeader)} onClick={()=>action(transition[0],c.id)}>{transition[1]}</Button>}{['en_revision','pendiente_aprobacion'].includes(c.status)&&<Button danger secondary icon={X} disabled={!editable||!isLeader||busy} onClick={()=>openForm('reject',c)}>Rechazar con motivo</Button>}{c.status==='en_renovacion'&&<div className="callout">La renovación está propuesta. La configuración final de su nueva ruta de revisión se valida durante la implementación.</div>}</>}
    {detailTab==='obligaciones'&&<><div className="detail-section-heading"><h3>Compromisos del expediente</h3><Button small icon={Plus} disabled={!editable} onClick={()=>openForm('obligation',c)}>Agregar</Button></div>{ownObligations.length?ownObligations.map(o=><article className="obligation-card" key={o.id}><Badge status={o.status}/><h3>{o.title}</h3><p>{o.owner} · {date(o.due_date)}</p>{o.evidence&&<div className="callout">{o.evidence}</div>}{o.status!=='completada'&&<Button small secondary icon={Check} disabled={!editable} onClick={()=>openForm('complete',o)}>Registrar cumplimiento</Button>}</article>):<Empty title="Sin obligaciones registradas" text="Agregue responsables y fechas para activar el seguimiento."/>}</>}
    {detailTab==='historial'&&<><h3>Historia del expediente</h3><div className="timeline">{[...(c.history||[])].reverse().map((h,i)=><div key={i}><span className="timeline-icon"><History size={15}/></span><div><b>{label(h.status)}</b><p>{h.note||'Estado registrado'}</p><small>{date(h.at)} · {h.by}</small></div></div>)}</div></>}
    </div><div className="drawer-foot"><ShieldCheck size={15}/>{editable?'Operación permitida por su perfil':'Acceso de consulta; no permite edición'} · Datos sintéticos</div></>:campaign?<div className="drawer-body"><div className="detail-facts"><div><small>Destinatarios</small><b>{c.contact_ids?.length||0}</b></div><div><small>Enviados</small><b>{c.sent_count||0}</b></div><div><small>Aprobación</small><b>{c.approved_by||'Pendiente'}</b></div><div><small>Omitidos</small><b>{c.skipped_count||0}</b></div></div><CampaignQualification campaign={c} companies={S.companies||[]}/><CampaignEditor campaign={c} editable={editable} canApprove={["regional","manager","superadmin"].includes(S.viewer?.role)} action={action} busy={busy}/><div className="callout">Editar o regenerar un mensaje invalida su aprobación. Respuestas y exclusiones cancelan los seguimientos pendientes. Ningún correo sale de esta demostración.</div><h3>Destinatarios</h3><div className="recipient-list">{(c.contact_ids||[]).map(id=>{const p=(S.contacts||[]).find(x=>x.id===id);return p?<div key={id}><Avatar name={p.name} small/><span>{p.name}<small>{p.email}</small></span><Badge status={p.status}/></div>:null})}</div></div>:company?<div className="drawer-body"><CompanyIntelligence company={c} S={S} action={action} busy={busy} readOnly={!editable} openForm={openForm} compact/><h3 className="spaced-title">Contactos de esta empresa</h3><div className="recipient-list">{(S.contacts||[]).filter(p=>p.company_id===c.id).map(p=><button key={p.id} onClick={()=>openDetail(p)}><Avatar name={p.name}/><span><b>{p.name}</b><small>{p.title}</small></span><ChevronRight size={17}/></button>)}</div></div>:<div className="drawer-body"><div className="detail-facts"><div><small>Correo sintético</small><b>{c.email}</b></div><div><small>Cargo</small><b>{c.title}</b></div><div><small>Fuente</small><b>{c.source}</b></div><div><small>Afinidad</small><b>{c.score||'—'} / 100</b></div></div><div className="button-stack"><Button secondary icon={MessagesSquare} disabled={!editable||c.excluded||busy} onClick={()=>openForm('reply',c)}>Registrar respuesta simulada</Button><Button icon={CalendarDays} disabled={!editable||c.excluded} onClick={()=>openForm('meeting',c)}>Agendar reunión</Button><Button secondary disabled={!editable} onClick={()=>openForm('editcontact',c)}>Editar contacto</Button><Button secondary danger icon={X} disabled={!editable||c.excluded} onClick={()=>openForm('exclude',c)}>Excluir de comunicaciones</Button></div>{c.excluded&&<div className="callout warning">Contacto excluido: {c.exclusion_reason}. No podrá participar en nuevas campañas.</div>}<h3 className="spaced-title">Cronología del contacto</h3><div className="timeline">{[...(S.messages||[]).filter(x=>x.contact_id===c.id).map(x=>({...x,title:x.subject,date:x.created_at,description:x.body})),...(S.activities||[]).filter(x=>x.contact_id===c.id)].sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(x=><div key={x.id}><span className="timeline-icon">{x.type==='meeting'?<CalendarDays size={15}/>:<Mail size={15}/>}</span><div><b>{x.title}</b><p>{x.description}</p><small>{date(x.date)}{x.followup_status&&` · Seguimiento ${label(x.followup_status)}`}</small></div></div>)}</div></div>}
    </aside></div>
  }
  if(!app)return <React.Suspense fallback={<div className="presentation-loading" role="status">Preparando las iniciativas Vertia…</div>}><PresentationHub/></React.Suspense>;
  const sectionLabel=NAV[app].find(x=>x[0]===section)?.[1];
  return <div className={`app ${crm?'theme-global':'theme-vertia'}`}><div className="mobile-scrim" hidden={!mobile} onClick={()=>setMobile(false)}/><aside className={`sidebar ${mobile?'open':''}`}><a href="/" className={`brand ${crm?'global-brand':''}`}><img src={crm?'/brand/global-oficial.webp':'/brand/vertia.webp'} alt={crm?'Global Vía Pública':'Vertia Group'} width={crm?721:500} height={crm?207:180}/></a><div className="workspace-label"><span className="workspace-icon">{crm?<Target size={17}/>:<FolderOpen size={17}/>}</span><span>{crm?'Prospectador':'Gestión contractual'}<small>Workspace regional</small></span></div><span className="nav-label">ESPACIO DE TRABAJO</span><nav className="side-nav">{NAV[app].map(([id,title,I])=><button key={id} className={section===id?'active':''} onClick={()=>go(id)}><I size={18}/><span>{title}</span>{id==='trabajo'&&m.pending_approval>0&&<em>{m.pending_approval}</em>}</button>)}</nav><div className="sidebar-bottom"><a href={`/propuestas/${app}.html`} target="_blank" rel="noreferrer"><FileText size={17}/> Propuesta comercial <ArrowUpRight size={15}/></a><a href="/"><Globe2 size={17}/> Ver las iniciativas <ArrowUpRight size={15}/></a><div className="sidebar-demo"><span className="live-dot"/><div>Entorno de demostración<small>{crm?'Cartera y contactos de ejemplo':'Catálogo de ejemplo y archivos cargados'}</small></div></div><div className="powered">DESARROLLADO POR <img src="/brand/moai.png" alt="MoAI"/></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-btn menu-toggle" aria-label="Abrir menú" onClick={()=>setMobile(true)}><Menu size={22}/></button><span>{crm?'Prospectador':'Gestión contractual'}</span><ChevronRight size={14}/><b>{sectionLabel}</b></div><div className="topbar-tools"><label className="global-search"><Search size={17}/><input aria-label="Buscar en la vista actual" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar en esta vista…"/><kbd>⌕</kbd></label><div className="notification-wrap"><button className={`icon-btn bell ${notifications?'selected':''}`} aria-label="Ver notificaciones" onClick={()=>setNotifications(!notifications)}><Bell size={19}/>{(S.notifications||[]).length>0&&<i/>}</button>{notifications&&<div className="notification-menu"><h3>Notificaciones</h3>{(S.notifications||[]).slice(0,7).map(n=><div key={n.id}><Bell size={15}/><span>{n.title}<small>{date(n.created_at)}</small></span></div>)}{!(S.notifications||[]).length&&<p>No hay notificaciones en este perfil.</p>}</div>}</div><ThemeToggle/><span className="topbar-divider"/><Avatar name={S.viewer?.name||'Demo Regional'} small/><label className="profile-select"><span>Perfil de demostración · no SSO</span><select aria-label="Perfil de demostración" value={profile} onChange={e=>setProfile(e.target.value)}>{(S.users||[{id:'regional',name:'Regional'}]).map(u=><option key={u.id} value={u.id}>{u.name}{u.title?' · '+u.title:''}</option>)}</select></label></div></header><div className="contextbar"><div><span className="demo-pill"><span/> Demostración</span><span>{crm?'Cartera de ejemplo · Integraciones externas simuladas':'Catálogo de ejemplo · Carga y lectura de archivos reales'}</span></div><label className="country-selector"><Globe2 size={15}/><select aria-label="Filtrar país" value={country} onChange={e=>setCountry(e.target.value)}><option value="all">Todos los países visibles</option>{(S.countries||[]).map(c=><option key={c.code} value={c.code}>{c.name}</option>)}</select><ChevronDown size={13}/></label></div><main className="content">{drill&&<div className="drill-banner"><span>Origen del dashboard: <b>{drill.title}</b> · {drill.ids.length} registros</span><button onClick={()=>setDrill(null)}>Quitar filtro</button></div>}{loading?<div className="page-skeleton" role="status" aria-live="polite"><span className="sr-only">Preparando su espacio de trabajo. Consultando los registros autorizados en PostgreSQL.</span><div className="sk sk-eyebrow"/><div className="sk sk-title"/><div className="sk sk-text"/><div className="sk-metrics">{[0,1,2,3].map(i=><div className="sk sk-metric" key={i}/>)}</div><div className="sk-panels"><div className="sk sk-panel"/><div className="sk sk-panel"/></div></div>:error?<div className="page-error"><AlertCircle size={34}/><h2>No pudimos cargar el espacio de trabajo</h2><p>{error}</p><Button icon={RefreshCw} onClick={()=>refresh()}>Reintentar</Button></div>:<>{section==='resumen'&&<Overview/>}{section==='cartera'&&<Portfolio/>}{section==='descubrir'&&<ProspectingWorkbench S={S} companies={companies} contacts={contacts} prospects={prospects} action={action} busy={busy} readOnly={noCommercial} country={country} go={go} openDetail={openDetail} openForm={openForm}/>}{section==='enriquecer'&&<EnrichmentWorkspace S={S} action={action} busy={busy} readOnly={noCommercial}/>} {section==='campanas'&&<Campaigns/>}{section==='configuracion'&&(crm?<CommercialSettings S={S} action={action} busy={busy}/>:<ContractSettings S={S} action={action} busy={busy}/>)}{section==='seguimiento'&&<MailWorkspace S={{...S,messages:visible(S.messages,'messages'),activities}} action={action} busy={busy} readOnly={noCommercial} openForm={openForm} openDetail={openDetail}/>}{section==='resultados'&&<OpportunityBoard S={{...S,opportunities}} action={action} busy={busy} readOnly={noCommercial} openForm={openForm} country={country} query={query}/>}{section==='repositorio'&&<Repository/>}{section==='trabajo'&&<Repository work/>}{section==='antecedentes'&&<Repository antecedent/>}{section==='obligaciones'&&<Obligations/>}{section==='accesos'&&<Access/>}{section==='auditoria'&&<Audit/>}{section==='integraciones'&&<Integrations/>}{section==='roadmap'&&<Roadmap/>}{section==='flujo'&&<FlowModel app={app} S={S} go={go}/>}</>}</main><footer className="page-footer"><span>© {new Date().getFullYear()} {crm?'Global Vía Pública':'Vertia Group'} · Prototipo funcional</span><span><ShieldCheck size={13}/> Acceso según perfil · Persistencia PostgreSQL</span></footer></div>{detail&&Detail()}{modal&&renderForm()}{toast&&<div className={`toast ${toast.type}${toast.moment?' toast-moment':''}`} role="status" key={toast.title||toast.message}>{toast.type==='error'?<AlertCircle size={20}/>:<CheckCircle2 size={20}/>}<span>{toast.title&&<b className="toast-title">{toast.title}</b>}{toast.message}</span><button onClick={()=>setToast(null)} aria-label="Cerrar notificación"><X size={16}/></button></div>}{busy&&<div className="busy-indicator" role="status"><span className="busy-line" aria-hidden="true"/> Guardando cambios</div>}</div>
}
function CampaignEditor({campaign:c,editable,canApprove,action,busy}){
  const [subject,setSubject]=useState(c.subject||''),[body,setBody]=useState(c.body||'');
  useEffect(()=>{setSubject(c.subject||'');setBody(c.body||'')},[c.id,c.subject,c.body]);
  const dirty=subject!==c.subject||body!==c.body;
  return <><form className="campaign-editor" onSubmit={e=>{e.preventDefault();action('set_campaign_content',c.id,{subject,body})}}><label className="field"><span>Asunto</span><input required value={subject} onChange={e=>setSubject(e.target.value)} disabled={!editable||c.status==='enviada'}/></label><label className="field"><span>Mensaje</span><textarea rows={7} required value={body} onChange={e=>setBody(e.target.value)} disabled={!editable||c.status==='enviada'}/></label>{c.status!=='enviada'&&<Button secondary small type="submit" disabled={!editable||busy||!dirty} icon={Check}>Guardar edición · requiere nueva aprobación</Button>}</form>{dirty&&<div className="callout warning">Guarde sus cambios antes de aprobar o enviar esta campaña.</div>}<div className="button-stack">{c.status!=='enviada'&&<><Button secondary icon={WandSparkles} disabled={busy||!editable} onClick={()=>action('draft_campaign',c.id)}>Generar borrador con Claude · Simulado</Button><Button secondary icon={Check} disabled={dirty||busy||!editable||!canApprove||c.status==='aprobada'} onClick={()=>action('approve_campaign',c.id)}>Aprobar campaña</Button><Button icon={Send} disabled={dirty||busy||!editable||c.status!=='aprobada'} onClick={()=>action('send_campaign',c.id)}>Enviar campaña · Simulado</Button></>}</div></>
}
createRoot(document.getElementById('root')).render(<App/>);
